import licenseNotices from "../THIRD-PARTY-LICENSES.txt" with { type: "text" };

/**
 * `mdview`'s command-line surface (WP-4).
 *
 * The one non-negotiable shape: `mdview <file.md>` must keep working with no
 * subcommand — that invocation predates subcommands and is the one the user
 * runs daily. Subcommands (`highlight-as`, `help`, and the `view` alias for
 * the default itself) sit *alongside* it, not in front of it: `main` only
 * dispatches to a named subcommand handler when the first argument is
 * exactly one of those names; anything else — including every existing flag,
 * which all start with `-` — falls through to the same view path a bare file
 * argument always used. `probe` (WP-3) landed as exactly that: a fourth
 * subcommand name, with nothing about this dispatch changed to accommodate it.
 *
 * `--probe` is *also* accepted as a flag on the view path, because this repo
 * documents both spellings — `plans/crucible-tui-launch.md`'s "Public
 * Interfaces" section says `mdview --probe` while its WP-3 text says
 * subcommand. Supporting both is cheaper than making one of two published
 * spellings a lie, and the flag is a one-line delegation to the same handler.
 */
const USAGE = `usage: mdview <file.md> [--width N] [--no-pager] [--check] [--ascii|--unicode] [--color[=WHEN]] [--help] [--licenses]

  <file.md>       markdown file to render (required unless --licenses or
                  --probe is given)
  --width N       target render width (default: terminal columns, else 100)
  --color[=WHEN]  when to emit colour: auto (the default), always, or never.
                  Bare --color means --color=always. Repeated, the last one
                  wins
  --no-pager      write plain output to stdout instead of piping to a pager
  --check         render with no pager; exit non-zero if any line exceeds the
                  target width (this tool's self-smoke gate)
  --ascii         force the ASCII glyph tier (bullets, rules, table borders,
                  task states) regardless of detected terminal capability
  --unicode       force the Unicode glyph tier; mutually exclusive with --ascii
  --probe         run the terminal ambiguous-width diagnostic and exit; the
                  same thing as \`mdview probe\` (no file argument needed)
  --help, -h      print this message and exit
  --licenses      print aggregated third-party license notices and exit (no
                  file argument needed; see THIRD-PARTY-LICENSES.txt)

Glyph tier resolution (highest precedence first): --ascii/--unicode, then
MDVIEW_GLYPHS=ascii|unicode in the environment, then auto-detection from the
locale and TERM.

Colour resolution (highest precedence first): --color, then
MDVIEW_COLOR=auto|always|never, then NO_COLOR (present at all, even empty,
means never), then FORCE_COLOR (0/false mean never; empty, true and 1-3 mean
always; any other value decides nothing), then the config file's "color" key,
then whether stdout is a terminal. Piped output is therefore colourless unless
you ask for colour explicitly.

OSC-8 hyperlinks are a separate axis: never off a terminal, whatever the colour
setting says. On a terminal, MDVIEW_HYPERLINKS=auto|always|never decides, and
auto asks what the terminal advertises.

Ambiguous-width resolution (highest precedence first): MDVIEW_AMBIGUOUS=narrow|wide
in the environment, then a cached probe result for this terminal, then a live
probe when both stdin and stdout are TTYs, then narrow. Run \`mdview probe\` to
see which rule won and why.

Subcommands (a bare <file.md> above is still valid on its own — no subcommand
is required to view a file):
  highlight-as <fence> <language>   map a fence language to a highlighter
                                     language and save it to the config file
  probe [--refresh]                 report how this terminal renders East Asian
                                     Ambiguous characters
  view <file.md> [options]          same as the bare form above, spelled out
  help [subcommand]                 print this message, or a subcommand's own

Run \`mdview <subcommand> --help\` or \`mdview help <subcommand>\` for a
subcommand's own usage.
`;

const HIGHLIGHT_AS_USAGE = `usage: mdview highlight-as <fence> <language>

  <fence>       fence info-string language to alias (e.g. dataviewjs)
  <language>    highlighter language to render it as — validated against
                highlight.js's supported list before anything is written
  --help, -h    print this message and exit

Records "<fence> -> <language>" into the user config (the XDG config path;
see \`mdview help\` for its precedence), layered over the built-in aliases
(dataviewjs -> javascript, dataview -> sql). A user entry for a fence that
also has a built-in default wins. The write only ever touches this one entry:
every other config key, and every other highlight-as mapping, is left as-is.
`;

const PROBE_USAGE = `usage: mdview probe [--refresh] [--no-cache] [--timeout MS]

  --refresh     ignore any cached answer and re-probe the terminal
  --no-cache    do not write the result to the cache
  --timeout MS  how long to wait for the terminal's DSR reply (default: 200)
  --help, -h    print this message and exit

Reports how this terminal renders East Asian **Ambiguous** characters — the
class that almost every non-ASCII character in real prose belongs to (— – → ←
… ≥ × • ○ and the whole box-drawing set). Such a character is 1 column in some
terminals and 2 in others, and there is no way to tell from the byte, so the
viewer has to ask.

The probe writes one test glyph (${PROBE_GLYPH}) at the cursor, asks the terminal for
the cursor position before and after with DSR (\\e[6n), and takes the difference.
It reads the reply in raw mode with a short timeout, restores cooked mode on
every exit path, and erases the glyph afterwards, so it leaves nothing behind.
It runs only when stdin and stdout are both TTYs — never under --check, never
in the sweep, never when piped.

The answer is cached per terminal identity (TERM, TERM_PROGRAM, COLORTERM,
VTE_VERSION, the multiplexer, and the locale) so a second terminal never
inherits the first one's answer. Set MDVIEW_AMBIGUOUS=narrow|wide to override
everything, including the cache.
`;

export interface CliOptions {
  file: string;
  width?: number;
  noPager: boolean;
  check: boolean;
  help: boolean;
  licenses: boolean;
  /** `--probe` on the view path: run the diagnostic instead of rendering. */
  probe: boolean;
  glyphTier?: GlyphTier;
  /**
   * `--color[=auto|always|never]`, the highest slot in the colour matrix
   * (`src/colour.ts`). Absent when the flag was not given — which is **not** the same as
   * `"auto"` from this parser's point of view, even though the two resolve identically:
   * `undefined` is the field's own default and `"auto"` is something the user typed.
   */
  color?: ColourDirective;
}

/**
 * Resolve the target render width.
 * Precedence: explicit --width, then the terminal's reported column count,
 * then a fixed fallback so headless/redirected runs stay deterministic.
 */
export function resolveWidth(explicit: number | undefined, columns: number | undefined): number {
  if (explicit !== undefined) return explicit;
  if (columns !== undefined && columns > 0) return columns;
  return 100;
}

export function parseArgs(args: string[]): CliOptions {
  let file: string | undefined;
  let width: number | undefined;
  let noPager = false;
  let check = false;
  let help = false;
  let licenses = false;
  let probe = false;
  let glyphTier: GlyphTier | undefined;
  let color: ColourDirective | undefined;

  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (arg === "--help" || arg === "-h") {
      help = true;
      continue;
    }
    if (arg === "--licenses") {
      licenses = true;
      continue;
    }
    if (arg === "--probe") {
      probe = true;
      continue;
    }
    if (arg === "--no-pager") {
      noPager = true;
      continue;
    }
    if (arg === "--check") {
      check = true;
      continue;
    }
    if (arg === "--ascii" || arg === "--unicode") {
      const requested: GlyphTier = arg === "--ascii" ? "ascii" : "unicode";
      if (glyphTier !== undefined && glyphTier !== requested) {
        throw new Error("--ascii and --unicode are mutually exclusive");
      }
      glyphTier = requested;
      continue;
    }
    // `--color` and `--color=WHEN`, in the flat pattern every other flag here uses.
    //
    // Three edges, all of them named in the ratified spec (`plans/colour-policy.md`,
    // Decision 2) rather than invented here: **bare means `always`** (a user who typed the
    // flag with no value is asking for colour, not asking for the default they already
    // had); **repeated, the last one wins** (plain assignment, so `--color=never --color`
    // is `always`); and **an unrecognised value is a CLI error**, unlike the same value in
    // the environment, which is noted and ignored. The asymmetry is deliberate: a typo on
    // the command line is a mistake being made right now and can be corrected right now; a
    // typo in an exported variable would otherwise refuse to render every document for the
    // rest of that shell's life.
    //
    // Note the value is **not** consumed as a separate argument. `--color never` would
    // leave `never` to be taken as the file name, and this flag has to work with no value
    // at all, so the two spellings cannot be told apart positionally.
    if (arg === "--color" || arg?.startsWith("--color=")) {
      if (arg === "--color") {
        color = "always";
      } else {
        const raw = arg.slice("--color=".length);
        const parsed = parseColourDirective(raw);
        if (parsed === undefined) {
          throw new Error(`--color must be auto, always or never, got: ${raw}`);
        }
        color = parsed;
      }
      continue;
    }
    if (arg === "--width") {
      const value = args[index + 1];
      if (!value) throw new Error("missing value for --width");
      const parsed = Number(value);
      if (!Number.isFinite(parsed) || parsed <= 0) {
        throw new Error(`--width must be a positive number, got: ${value}`);
      }
      width = parsed;
      index += 1;
      continue;
    }
    if (arg?.startsWith("-")) {
      throw new Error(`unknown argument: ${arg}`);
    }
    if (file !== undefined) {
      throw new Error(`unexpected extra argument: ${arg}`);
    }
    file = arg;
  }

  if (!help && !licenses && !probe && !file) {
    throw new Error("missing required argument: <file.md>");
  }

  return { file: file ?? "", width, noPager, check, help, licenses, probe, glyphTier, color };
}

async function runPager(output: string): Promise<void> {
  await new Promise<void>((resolvePromise) => {
    let child;
    try {
      child = spawn("less", ["-R"], { stdio: ["pipe", "inherit", "inherit"] });
    } catch {
      process.stdout.write(output);
      resolvePromise();
      return;
    }

    child.on("error", () => {
      // `less` missing or unusable — fall back to plain stdout.
      process.stdout.write(output);
      resolvePromise();
    });
    child.on("exit", () => {
      resolvePromise();
    });
    child.stdin?.write(output);
    child.stdin?.end();
  }).catch(() => {
    // Swallow: fallback already wrote plain output above.
  });
}

/**
 * The default (and implicit) subcommand: render a file. Unchanged from the
 * tool's pre-subcommand behavior, plus one addition — loading the user's
 * `highlightAs` config and building a fence-language resolver from it
 * (`src/lang.ts`'s `makeFenceLanguageResolver`), which is then handed to the
 * render call, so a `highlight-as` write actually takes effect on the next view.
 *
 * **This is the last consumer of F4's removed module global** (WP-3 of
 * `plans/marked-terminal-replacement.md`). It used to call `setHighlightAliases`,
 * which mutated `src/lang.ts`'s `effectiveAliases` for the whole process, because
 * `render.ts` reached the resolver by module import and there was nothing to pass
 * a configured map through. There is now: the resolver is a value, it goes on the
 * `LayoutContext`, and this function is where it is built — once, from config,
 * before any rendering happens.
 */
async function runView(args: string[]): Promise<void> {
  const options = parseArgs(args);

  if (options.help) {
    process.stdout.write(USAGE);
    return;
  }

  // Takes no file argument, so it must be handled here — before the readFile
  // call below demands one — exactly like --help above.
  if (options.licenses) {
    process.stdout.write(licenseNotices);
    return;
  }

  // Same shape, same reason: `mdview --probe` is the flag spelling of
  // `mdview probe`, so it delegates rather than reimplementing the diagnostic.
  if (options.probe) return runProbe([]);

  let source: string;
  try {
    source = await readFile(options.file, "utf8");
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`cannot read file: ${options.file} (${reason})`);
  }

  const config = await loadConfig();
  const resolveFenceLanguageFor = makeFenceLanguageResolver(config.highlightAs);

  const targetWidth = resolveWidth(options.width, process.stdout.columns);
  // **`allowProbe` is off under `--check`, and that is the load-bearing half of
  // this call** (WP-3). `--check` is a gate: it must not touch the terminal, must
  // not depend on a DSR reply arriving, and must not write a cache file as a side
  // effect of running a test. The env var and a cache entry are still honoured —
  // a gate that measured narrow while the user's own renders measure wide would
  // be checking a document nobody is going to see.
  const ambiguous = await resolveAmbiguousWidth({ allowProbe: !options.check });
  const glyphs = resolveGlyphs(process.env, options.glyphTier, ambiguous.ambiguous);
  // Never silently: the tier was taken out of the user's hands by arithmetic they
  // cannot see (see `wideForcesAscii`), so it is named, once, with the way out.
  if (wideForcesAscii(options.glyphTier, ambiguous.ambiguous)) {
    process.stderr.write(
      "mdview: --unicode ignored — this terminal measures East Asian Ambiguous characters " +
        "as 2 columns, and the Unicode box-drawing set is ambiguous, so tables cannot be laid " +
        "out with it. Set MDVIEW_AMBIGUOUS=narrow to override (see `mdview probe`).\n",
    );
  }
  // **The one colour decision, resolved here and nowhere else** (WP-1 of
  // `plans/colour-policy.md`), beside the width and the glyph tier because it is the same
  // kind of thing: an environment-dependent answer this entry point owns so the renderer
  // does not have to.
  //
  // `process.stdout.isTTY` is read **before** the pager is spawned, deliberately.
  // `runPager` pipes into `less -R`, so by the time the render is written stdout is a pipe
  // — and resolving colour from that would make the paged view, which is the interactive
  // case, the only one that never gets colour. The stream this asks about is the one the
  // user is looking at.
  const policy = resolveColourPolicy({
    flag: options.color,
    config: config.color,
    env: process.env,
    isTTY: process.stdout.isTTY === true,
    platform: process.platform,
    warn: (message) => process.stderr.write(`${message}\n`),
  });

  const { text: output, codeRanges } = renderDocumentDetailed(
    source,
    targetWidth,
    glyphs,
    ambiguous.measure,
    config.emoji,
    resolveFenceLanguageFor,
    policy,
  );

  if (options.check) {
    // The one width gate (`src/overflow.ts`), not a second copy of it. `ambiguous.measure`
    // is the ruler this render was actually allocated with — see that module for why a
    // check measured with any other one is asserting something else entirely.
    const overflow = findFirstOverflow(output, targetWidth, codeRanges, ambiguous.measure);
    if (overflow) {
      throw new Error(
        `line ${overflow.line} exceeds target width ${targetWidth} (measured ${overflow.width})`,
      );
    }
    process.stdout.write(output);
    return;
  }

  const usePager = process.stdout.isTTY && !options.noPager;
  if (usePager) {
    await runPager(output);
    return;
  }

  process.stdout.write(output);
}

/** `mdview highlight-as <fence> <language>` — validates, then writes back to the config. */
async function runHighlightAs(args: string[]): Promise<void> {
  if (args.some((arg) => arg === "--help" || arg === "-h")) {
    process.stdout.write(HIGHLIGHT_AS_USAGE);
    return;
  }

  const flags = args.filter((arg) => arg.startsWith("-"));
  if (flags.length > 0) {
    throw new Error(`highlight-as: unknown argument: ${flags[0]} (run \`mdview highlight-as --help\`)`);
  }

  const positional = args.filter((arg) => !arg.startsWith("-"));
  if (positional.length !== 2) {
    throw new Error(
      `highlight-as: expected exactly 2 arguments <fence> <language>, got ${positional.length} ` +
        "(run `mdview highlight-as --help`)",
    );
  }

  const [fence, language] = positional as [string, string];
  if (!isSupportedLanguage(language)) {
    throw new Error(
      `highlight-as: unsupported language "${language}" — highlight.js does not recognize it, so ` +
        "the fence would render unhighlighted rather than mysteriously plain later. Common valid " +
        'targets: javascript, typescript, python, bash, sql, json, yaml, plaintext ("plaintext" is ' +
        "always accepted, if the fence should just not be highlighted).",
    );
  }

  const result = await writeHighlightAlias(fence, language);
  const normalizedFence = fence.trim().toLowerCase();
  const normalizedLanguage = language.trim().toLowerCase();
  process.stdout.write(
    `mdview: ${result.created ? "created" : "updated"} config at ${result.path} — ` +
      `"${normalizedFence}" now highlights as "${normalizedLanguage}"\n`,
  );
}

/**
 * Format a resolution as the diagnostic a human pastes back.
 *
 * Exported so `tests/width.test.ts` can assert its shape without a subprocess and
 * without a terminal — the same reason `main` is exported. **The audience is a user
 * in a terminal the maintainer cannot observe**, which sets the content: every input
 * the resolution consumed is echoed (so a wrong answer can be diagnosed from the
 * paste alone), the winning precedence rule is named outright rather than implied,
 * and cache-vs-live-probe is stated in as many words, because "it says wide" and
 * "it said wide once, months ago, in a different terminal" are different facts.
 */
export function formatProbeReport(resolution: AmbiguousResolution, env: NodeJS.ProcessEnv): string {
  const multiplexer = env.ZELLIJ || env.ZELLIJ_SESSION_NAME ? "zellij" : env.TMUX ? "tmux" : env.STY ? "screen" : "none";
  const lines: string[] = [
    "mdview probe — East Asian Ambiguous width",
    "",
    "terminal",
    `  TERM             ${env.TERM ?? "(unset)"}`,
    `  TERM_PROGRAM     ${env.TERM_PROGRAM ?? "(unset)"}`,
    `  COLORTERM        ${env.COLORTERM ?? "(unset)"}`,
    `  VTE_VERSION      ${env.VTE_VERSION ?? "(unset)"}`,
    `  multiplexer      ${multiplexer}`,
    `  locale           ${env.LC_ALL || env.LC_CTYPE || env.LANG || "(unset)"}`,
    `  stdin is a TTY   ${process.stdin.isTTY ? "yes" : "no"}`,
    `  stdout is a TTY  ${process.stdout.isTTY ? "yes" : "no"}`,
    `  columns          ${process.stdout.columns ?? "(unknown)"}`,
    "",
    "probe",
  ];

  if (resolution.probe) {
    const probe = resolution.probe;
    lines.push(`  test glyph       ${PROBE_GLYPH} (U+2014 EM DASH)`);
    lines.push(`  DSR reply        ${probe.reply ?? "(none)"}`);
    lines.push(
      `  cursor column    ${probe.columns ? `${probe.columns.before} -> ${probe.columns.after}` : "(not reported)"}`,
    );
    lines.push(`  measured width   ${probe.glyphColumns ?? "(not derivable)"}`);
    lines.push(`  elapsed          ${probe.elapsedMs}ms`);
    lines.push(`  outcome          ${probe.detail}`);
  } else {
    lines.push("  not run          no live probe was needed or permitted on this run");
  }

  lines.push(
    "",
    "result",
    `  ambiguous width  ${resolution.ambiguous}`,
    `  decided by       ${resolution.source}${resolution.source === "cache" ? " (NOT a live probe)" : ""}`,
    `  because          ${resolution.detail}`,
    "",
    "cache",
    `  file             ${resolution.cachePath}`,
    `  identity         ${resolution.identity}`,
    "",
    "Precedence, highest first: MDVIEW_AMBIGUOUS=narrow|wide, then this cache,",
    "then a live DSR probe (needs stdin and stdout to both be TTYs), then narrow.",
    "Re-probe with `mdview probe --refresh`; override with MDVIEW_AMBIGUOUS.",
    "",
  );
  return lines.join("\n");
}

/**
 * `mdview probe [--refresh] [--no-cache] [--timeout MS]` — the terminal diagnostic.
 *
 * This is the one code path in the tool that is *allowed* to probe by default: the
 * user typed the word "probe", which is as explicit as consent gets. Everything else
 * — including the view path — either inherits a cached answer or does without.
 */
async function runProbe(args: string[]): Promise<void> {
  if (args.some((arg) => arg === "--help" || arg === "-h")) {
    process.stdout.write(PROBE_USAGE);
    return;
  }

  let refresh = false;
  let noCache = false;
  let timeoutMs: number | undefined;
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (arg === "--refresh") {
      refresh = true;
      continue;
    }
    if (arg === "--no-cache") {
      noCache = true;
      continue;
    }
    if (arg === "--timeout") {
      const value = args[index + 1];
      const parsed = Number(value);
      if (!Number.isFinite(parsed) || parsed <= 0) {
        throw new Error(`probe: --timeout must be a positive number of milliseconds, got: ${value}`);
      }
      timeoutMs = parsed;
      index += 1;
      continue;
    }
    throw new Error(`probe: unknown argument: ${arg} (run \`mdview probe --help\`)`);
  }

  const resolution = await resolveAmbiguousWidth({ allowProbe: true, refresh, noCache, timeoutMs });
  process.stdout.write(formatProbeReport(resolution, process.env));
}

/** `mdview help [subcommand]` — prints top-level help, or one subcommand's own. */
async function runHelp(args: string[]): Promise<void> {
  const [name] = args;
  if (name === undefined || name === "view" || name === "help") {
    process.stdout.write(USAGE);
    return;
  }
  if (name === "highlight-as") {
    process.stdout.write(HIGHLIGHT_AS_USAGE);
    return;
  }
  if (name === "probe") {
    process.stdout.write(PROBE_USAGE);
    return;
  }
  throw new Error(`help: unknown subcommand: ${name} (expected one of: view, highlight-as, probe, help)`);
}

export async function main(args = Bun.argv.slice(2)): Promise<void> {
  const [first, ...rest] = args;

  if (first === "highlight-as") return runHighlightAs(rest);
  if (first === "help") return runHelp(rest);
  if (first === "probe") return runProbe(rest);
  if (first === "view") return runView(rest);

  // No recognized subcommand name in the lead position — including every
  // existing flag, which all start with "-" and therefore never match one of
  // the four names above. This is the compatibility path: a bare
  // `mdview FILE.md` (with flags in any position) behaves exactly as it did
  // before subcommands existed.
  return runView(args);
}

// Errors reach the user as one line naming the problem, never as a stack trace.
// `main` itself still throws — tests call it directly and assert on the thrown
// message, and that contract is what keeps the suite subprocess-free — so the
// catch lives here, at the process boundary, and nowhere else. Without it Bun
// prints a source excerpt, a stack, and its own version banner around every
// message this file carefully worded, and leaks the absolute install path while
// doing it.
if (import.meta.main) {
  try {
    await main();
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`mdview: ${message}\n`);
    process.exit(1);
  }
}
